enum RoundSeed { Segment(pb::InferResponse), InPlace(Box<Restored>), Parked(Box<park::ParkSeed>) }
struct Continuation { release: Option<ApprovedRelease>, /* rest committed */ }
async fn run_agent_with_route(/* committed params */, park: Option<park::ParkClaim>) -> Result<pb::RunAgentResponse, Status>;
// resume.rs Refusal: + ParkNotRestorable => "park_not_restorable", ParkRouteUnavailable => "park_route_unavailable" (FailedPrecondition)

// session-core
loop_checkpoint: pub(crate) fn park_ttl_seconds() -> i64; pub(crate) struct Claimed { /* committed */ pause_ref: String }
pub(crate) async fn park_crashed(tx: &mut Transaction<'_, Postgres>, cipher: &DescriptorCipher, run_id: &str, seq: i64) -> Result<bool, Status>;
terminalization: pub(crate) fn park_recovery_enabled() -> bool; // SESSION_CORE_PARK_RECOVERY_ENABLED
park_recovery: pub(crate) enum RecoveryHold { Terminalize, Spare, CrashPark }
pub(crate) struct HoldRow { state: String, kind: String, seq: i64, updated_at: DateTime<Utc>, claim_expires_at: Option<DateTime<Utc>> }
pub(crate) struct CrashFacts { pending_approval_any_expiry: bool, ledger_after_fold: bool, ledger_open: bool }
pub(crate) fn decide_hold(row: Option<&HoldRow>, facts: &CrashFacts, now: DateTime<Utc>, ttl_secs: i64, active: bool) -> RecoveryHold; // fold-content checks happen in park_crashed
pub(crate) async fn recovery_hold(tx: &mut Transaction<'_, Postgres>, run_id: &str, ttl_secs: i64) -> Result<(RecoveryHold, Option<i64 /*seq*/>), Status>;
SQL: CLAIM_PARK_SQL = "UPDATE run_loop_checkpoints SET state='resuming', claim_token_hash=$2, claim_expires_at=now()+make_interval(secs=>$3) WHERE run_id=$1 AND kind='park' AND (state='parked' OR (state='resuming' AND claim_expires_at < now())) RETURNING seq, ciphertext, segment_no, authority_digest, kind, pause_ref"

// Proto
execution.proto RunAgentResponse { ... string park_reason = 11; }
orchestration.proto OrchestrationEvent.oneof { RunParked run_parked = 24; RunResumed run_resumed = 25; }
message RunParked { string run_id = 1; string reason = 2; optional uint64 retry_after_ms = 3; string resets_at = 4; }
message RunResumed { string run_id = 1; uint32 segment_no = 2; string park_reason = 3; }
// AgentResume (unchanged fields): mode "park" => approval_id/step_id/tool_name/action_fingerprint/brief empty, claim_token set, segment_no 0 (ignored)

// HTTP / SSE
POST /api/v1/orchestration/runs/{run_id}/continue  SPA->BFF body {"claim_token": "..."} (no approval_id key); BFF->gateway {"approval_id":"","claim_token":"..."}
raw frame: event run_parked data {"run_id","reason"(closed),"retry_after_ms"?(u64),"resets_at"?(RFC3339 secs)}
orchestration SSE: run_parked (same keys), run_resumed {"run_id","segment_no","park_reason"}
New executor/frame tokens: park_not_restorable, park_route_unavailable. No new HTTP code.
// SPA
chatRunContinueInput = z.object({ runId: z.string().min(1), approvalId: z.string().min(1).optional(), claimToken: z.string().min(1) })
export async function continueParkedRun(runId: string, claimToken: string, onEvent: (e: SseEvent) => void, signal?: AbortSignal): Promise<void>
// Env: EXECUTION_LOOP_PARKING_ENABLED (execution-core, model-gateway; default false), SESSION_CORE_PARK_RECOVERY_ENABLED (default false), SESSION_CORE_PARK_TTL_SECONDS (default 86400, clamp 60..2592000).

